double _avg(List<int> xs) =>
    xs.isEmpty ? 0 : xs.reduce((a, b) => a + b) / xs.length;

int _p95(List<int> xs) {
  final sorted = List<int>.of(xs)..sort();
  return sorted[(sorted.length * 0.95).floor().clamp(0, sorted.length - 1)];
